// small heuristic: compute eviction hint score = ewma(kv_pressure, 0.2) * tenant_penalty
func computeHintScore(window []float64, penalty float64) float64 {
    // simplified: use ewma then scale
    s := ewma(window, 0.2)
    return s * penalty
}

